{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.dp_sku_dim as with raw as ( select upper(replace(sku_group,\' \',\'\')) as sku_key, replace(lower(trim(l1_category)),\' \',\'_\') as l1, replace(lower(trim(category)),\'inner wear\',\'innerwear\') as cat from snitch_db.maplemonk.meta_mapping_cogs_sku ), direct as ( select sku_key, l1, cat from raw qualify row_number() over (partition by sku_key order by case when l1=\'long_tail\' then 1 when l1=\'plus\' then 2 when l1=\'luxe\' then 3 when l1=\'snitch\' then 4 else 5 end, case when cat=\'shirts\' then 1 when cat=\'tshirts\' then 2 when cat=\'jeans\' then 3 when cat=\'trousers\' then 4 else 5 end) = 1 ), style as ( select iff(sku_key like \'MP%\' or sku_key like \'4C-%\', regexp_replace(sku_key,\'^([^-]+-[^-]+).*$\',\'\\1\'), regexp_replace(sku_key,\'-.*$\',\'\')) as style_key, coalesce(min(case when l1=\'long_tail\' then l1 end), min(case when l1=\'plus\' then l1 end), min(case when l1=\'luxe\' then l1 end), min(case when l1=\'snitch\' then l1 end), min(l1)) as l1, coalesce(min(case when cat=\'shirts\' then cat end), min(case when cat=\'tshirts\' then cat end), min(case when cat=\'jeans\' then cat end), min(case when cat=\'trousers\' then cat end), min(cat)) as cat from raw group by 1 ), universe as ( select upper(replace(sku_group,\' \',\'\')) as sku_key from snitch_db.maplemonk.inv_table_to_refer group by 1 union select upper(replace(sku_group,\' \',\'\')) from snitch_db.maplemonk.sales_data_view_for_refer group by 1 union select upper(replace(sku_group,\' \',\'\')) from snitch_db.maplemonk.inwards_base_table_for_refer group by 1 union select upper(replace(sku_group,\' \',\'\')) from snitch_db.maplemonk.putaway_base_table where lower(type) like \'store%return%\' group by 1 ), mapped as ( select u.sku_key, coalesce(d.l1, s.l1, \'unmapped\') as l1_raw, coalesce(d.cat, s.cat, \'unmapped\') as category, iff(d.sku_key is not null, \'direct\', iff(s.style_key is not null, \'style\', \'none\')) as match_type from universe u left join direct d on d.sku_key = u.sku_key left join style s on s.style_key = iff(u.sku_key like \'MP%\' or u.sku_key like \'4C-%\', regexp_replace(u.sku_key,\'^([^-]+-[^-]+).*$\',\'\\1\'), regexp_replace(u.sku_key,\'-.*$\',\'\')) ) select sku_key, l1_raw, category, match_type, case when l1_raw in (\'snitch\',\'plus\',\'luxe\',\'long_tail\') then l1_raw when l1_raw = \'unmapped\' then \'unmapped\' else \'other\' end as l1, case when l1_raw = \'long_tail\' then \'Long Tail\' when category = \'shirts\' then \'Shirts\' when category = \'tshirts\' then \'Tshirts\' when category = \'jeans\' then \'Jeans\' when category = \'trousers\' then \'Trousers\' when category in (\'hoodies\',\'jackets\',\'sweaters\',\'overshirt\',\'overshirts\') or category like \'%sweatshirt%\' or category like \'%trench%\' then \'Winterwear\' else \'Others\' end as grp from mapped; create or replace view snitch_db.maplemonk.dp_sales_daily as select s.date::date as date, case replace(replace(lower(trim(s.channel)),\' \',\'_\'),\'-\',\'_\') when \'shopify\' then \'Shopify\' when \'offline\' then \'Offline\' when \'mp_ppmp\' then \'MP\' when \'mp_flipkart_sor\' then \'MP-SOR\' when \'mp_slikk\' then \'MP-SOR\' when \'mp_myntra_sor\' then \'MP-SOR\' else \'UNMAPPED\' end as channel, s.channel as channel_raw, coalesce(d.l1,\'unmapped\') as l1, coalesce(d.category,\'unmapped\') as category, coalesce(d.grp,\'Others\') as grp, sum(s.quantity) as gross_qty, sum(s.sales) as gross_rev, sum(s.cost_price) as gross_cost, sum(s.net_quantity) as net_qty, sum(s.net_sales) as net_rev, sum(s.net_cost_price) as net_cost from snitch_db.maplemonk.sales_data_view_for_refer s left join snitch_db.maplemonk.dp_sku_dim d on d.sku_key = upper(replace(s.sku_group,\' \',\'\')) where s.date::date >= \'2026-01-01\' group by 1,2,3,4,5,6; create or replace view snitch_db.maplemonk.dp_inv_daily as with b as ( select i.date::date as d, upper(replace(i.sku_group,\' \',\'\')) as sku_key, coalesce(x.l1,\'unmapped\') as l1, coalesce(x.category,\'unmapped\') as category, upper(trim(i.size)) as size_n, sum(iff(lower(trim(i.channels))=\'warehouse\', greatest(i.inv,0), 0)) as wh_q, sum(iff(lower(trim(i.channels))=\'offline\', greatest(i.inv,0), 0)) as store_q, sum(iff(lower(trim(i.channels)) in (\'myntra sor\',\'flipkart sor\'), greatest(i.inv,0), 0)) as sor_q from snitch_db.maplemonk.inv_table_to_refer i left join snitch_db.maplemonk.dp_sku_dim x on x.sku_key = upper(replace(i.sku_group,\' \',\'\')) where i.date::date >= \'2026-01-01\' and upper(trim(i.size)) not in (\'7XL\',\'8XL\') and i.date::date <> \'2026-04-01\' and not (i.date::date between \'2026-05-06\' and \'2026-05-10\') group by 1,2,3,4,5 ), b2 as ( select d, sku_key, l1, category, size_n, wh_q, store_q, sor_q, wh_q + store_q as eco_q, iff(size_n in (\'XS\',\'S\',\'M\',\'L\',\'XL\',\'2XL\',\'3XL\',\'4XL\',\'5XL\',\'6XL\'),1,0) as is_std, case when l1 = \'plus\' then case size_n when \'3XL\' then 1 when \'4XL\' then 2 when \'5XL\' then 3 when \'6XL\' then 4 end else case size_n when \'S\' then 1 when \'M\' then 2 when \'L\' then 3 when \'XL\' then 4 end end as piv from b ), p as ( select d, sku_key, l1, category, sum(wh_q) as tot_wh, sum(iff(is_std=1,wh_q,0)) as std_wh, sum(iff(piv=1,wh_q,0)) as p1_wh, sum(iff(piv=2,wh_q,0)) as p2_wh, sum(iff(piv=3,wh_q,0)) as p3_wh, sum(iff(piv=4,wh_q,0)) as p4_wh, sum(store_q) as tot_store, sum(iff(is_std=1,store_q,0)) as std_store, sum(iff(piv=1,store_q,0)) as p1_store, sum(iff(piv=2,store_q,0)) as p2_store, sum(iff(piv=3,store_q,0)) as p3_store, sum(iff(piv=4,store_q,0)) as p4_store, sum(sor_q) as tot_sor, sum(iff(is_std=1,sor_q,0)) as std_sor, sum(iff(piv=1,sor_q,0)) as p1_sor, sum(iff(piv=2,sor_q,0)) as p2_sor, sum(iff(piv=3,sor_q,0)) as p3_sor, sum(iff(piv=4,sor_q,0)) as p4_sor, sum(eco_q) as tot_eco, sum(iff(is_std=1,eco_q,0)) as std_eco, sum(iff(piv=1,eco_q,0)) as p1_eco, sum(iff(piv=2,eco_q,0)) as p2_eco, sum(iff(piv=3,eco_q,0)) as p3_eco, sum(iff(piv=4,eco_q,0)) as p4_eco from b2 group by 1,2,3,4 ), f as ( select *, case when tot_wh<=0 then 0 when l1 = \'long_tail\' or std_wh = 0 then 1 when least(floor(p1_wh/2),floor(p2_wh/3),floor(p3_wh/3),floor(p4_wh/2)) > 5 then 1 else 0 end as nc1_wh, case when tot_wh<=0 then 0 when l1 = \'long_tail\' or std_wh = 0 then 1 when least(floor(p1_wh),floor(p2_wh/2),floor(p3_wh/2),floor(p4_wh)) > 5 then 1 else 0 end as nc2_wh, case when tot_wh<=0 then 0 when l1 = \'long_tail\' or std_wh = 0 then 1 when tot_wh >= 10 then 1 else 0 end as nc3_wh, case when tot_store<=0 then 0 when l1 = \'long_tail\' or std_store = 0 then 1 when least(floor(p1_store/2),floor(p2_store/3),floor(p3_store/3),floor(p4_store/2)) > 5 then 1 else 0 end as nc1_store, case when tot_store<=0 then 0 when l1 = \'long_tail\' or std_store = 0 then 1 when least(floor(p1_store),floor(p2_store/2),floor(p3_store/2),floor(p4_store)) > 5 then 1 else 0 end as nc2_store, case when tot_store<=0 then 0 when l1 = \'long_tail\' or std_store = 0 then 1 when tot_store >= 10 then 1 else 0 end as nc3_store, case when tot_sor<=0 then 0 when l1 = \'long_tail\' or std_sor = 0 then 1 when least(floor(p1_sor/2),floor(p2_sor/3),floor(p3_sor/3),floor(p4_sor/2)) > 5 then 1 else 0 end as nc1_sor, case when tot_sor<=0 then 0 when l1 = \'long_tail\' or std_sor = 0 then 1 when least(floor(p1_sor),floor(p2_sor/2),floor(p3_sor/2),floor(p4_sor)) > 5 then 1 else 0 end as nc2_sor, case when tot_sor<=0 then 0 when l1 = \'long_tail\' or std_sor = 0 then 1 when tot_sor >= 10 then 1 else 0 end as nc3_sor, case when tot_eco<=0 then 0 when l1 = \'long_tail\' or std_eco = 0 then 1 when least(floor(p1_eco/2),floor(p2_eco/3),floor(p3_eco/3),floor(p4_eco/2)) > 5 then 1 else 0 end as nc1_eco, case when tot_eco<=0 then 0 when l1 = \'long_tail\' or std_eco = 0 then 1 when least(floor(p1_eco),floor(p2_eco/2),floor(p3_eco/2),floor(p4_eco)) > 5 then 1 else 0 end as nc2_eco, case when tot_eco<=0 then 0 when l1 = \'long_tail\' or std_eco = 0 then 1 when tot_eco >= 10 then 1 else 0 end as nc3_eco from p ) select d as date, l1, category, sum(tot_wh) as inv_wh, count_if(tot_wh>0) as skus_wh, sum(iff(nc1_wh=1,tot_wh,0)) as nc1_inv_wh, sum(nc1_wh) as nc1_skus_wh, sum(iff(nc2_wh=1,tot_wh,0)) as nc2_inv_wh, sum(nc2_wh) as nc2_skus_wh, sum(iff(nc3_wh=1,tot_wh,0)) as nc3_inv_wh, sum(nc3_wh) as nc3_skus_wh, sum(tot_store) as inv_store, count_if(tot_store>0) as skus_store, sum(iff(nc1_store=1,tot_store,0)) as nc1_inv_store, sum(nc1_store) as nc1_skus_store, sum(iff(nc2_store=1,tot_store,0)) as nc2_inv_store, sum(nc2_store) as nc2_skus_store, sum(iff(nc3_store=1,tot_store,0)) as nc3_inv_store, sum(nc3_store) as nc3_skus_store, sum(tot_sor) as inv_sor, count_if(tot_sor>0) as skus_sor, sum(iff(nc1_sor=1,tot_sor,0)) as nc1_inv_sor, sum(nc1_sor) as nc1_skus_sor, sum(iff(nc2_sor=1,tot_sor,0)) as nc2_inv_sor, sum(nc2_sor) as nc2_skus_sor, sum(iff(nc3_sor=1,tot_sor,0)) as nc3_inv_sor, sum(nc3_sor) as nc3_skus_sor, sum(tot_eco) as inv_eco, count_if(tot_eco>0) as skus_eco, sum(iff(nc1_eco=1,tot_eco,0)) as nc1_inv_eco, sum(nc1_eco) as nc1_skus_eco, sum(iff(nc2_eco=1,tot_eco,0)) as nc2_inv_eco, sum(nc2_eco) as nc2_skus_eco, sum(iff(nc3_eco=1,tot_eco,0)) as nc3_inv_eco, sum(nc3_eco) as nc3_skus_eco, count_if(tot_wh+tot_store+tot_sor>0) as skus_all from f group by 1,2,3; create or replace view snitch_db.maplemonk.dp_flow_daily as with u as ( select date::date as date, upper(replace(sku_group,\' \',\'\')) as sku_key, qty as inward_qty, cogs_value as inward_cogs, 0 as sr_qty, 0 as sr_cogs from snitch_db.maplemonk.inwards_base_table_for_refer union all select date::date, upper(replace(sku_group,\' \',\'\')), 0, 0, qty, cogs_value from snitch_db.maplemonk.putaway_base_table where lower(type) like \'store%return%\' ) select u.date, coalesce(d.l1,\'unmapped\') as l1, coalesce(d.category,\'unmapped\') as category, sum(inward_qty) as inward_qty, sum(inward_cogs) as inward_cogs, sum(sr_qty) as store_return_qty, sum(sr_cogs) as store_return_cogs from u left join snitch_db.maplemonk.dp_sku_dim d on d.sku_key = u.sku_key where u.date >= \'2026-01-01\' group by 1,2,3; create or replace table snitch_db.maplemonk.dp_cell_daily as with sl as (select l1, category, grp from snitch_db.maplemonk.dp_sku_dim group by 1,2,3), cal as ( select dateadd(day, row_number() over (order by seq4()) - 1, \'2026-01-01\'::date) as d from table(generator(rowcount => 2000)) ), spine as ( select cal.d, sl.l1, sl.category, sl.grp from cal cross join sl where cal.d <= (select max(date) from snitch_db.maplemonk.dp_sales_daily) ), s as ( select date, l1, category, sum(iff(channel=\'Shopify\',gross_qty,0)) as shopify_gross_qty, sum(iff(channel=\'Shopify\',gross_rev,0)) as shopify_gross_rev, sum(iff(channel=\'Shopify\',gross_cost,0)) as shopify_gross_cost, sum(iff(channel=\'Shopify\',net_qty,0)) as shopify_net_qty, sum(iff(channel=\'Shopify\',net_rev,0)) as shopify_net_rev, sum(iff(channel=\'Shopify\',net_cost,0)) as shopify_net_cost, sum(iff(channel=\'MP\',gross_qty,0)) as mp_gross_qty, sum(iff(channel=\'MP\',gross_rev,0)) as mp_gross_rev, sum(iff(channel=\'MP\',gross_cost,0)) as mp_gross_cost, sum(iff(channel=\'MP\',net_qty,0)) as mp_net_qty, sum(iff(channel=\'MP\',net_rev,0)) as mp_net_rev, sum(iff(channel=\'MP\',net_cost,0)) as mp_net_cost, sum(iff(channel=\'Offline\',gross_qty,0)) as offline_gross_qty, sum(iff(channel=\'Offline\',gross_rev,0)) as offline_gross_rev, sum(iff(channel=\'Offline\',gross_cost,0)) as offline_gross_cost, sum(iff(channel=\'Offline\',net_qty,0)) as offline_net_qty, sum(iff(channel=\'Offline\',net_rev,0)) as offline_net_rev, sum(iff(channel=\'Offline\',net_cost,0)) as offline_net_cost, sum(iff(channel=\'MP-SOR\',gross_qty,0)) as sor_gross_qty, sum(iff(channel=\'MP-SOR\',gross_rev,0)) as sor_gross_rev, sum(iff(channel=\'MP-SOR\',gross_cost,0)) as sor_gross_cost, sum(iff(channel=\'MP-SOR\',net_qty,0)) as sor_net_qty, sum(iff(channel=\'MP-SOR\',net_rev,0)) as sor_net_rev, sum(iff(channel=\'MP-SOR\',net_cost,0)) as sor_net_cost, sum(iff(channel=\'MP-SOR\' and lower(channel_raw) not like \'%slikk%\', gross_qty, 0)) as sor_exslikk_qty, sum(iff(channel=\'MP-SOR\' and lower(channel_raw) not like \'%slikk%\', net_qty, 0)) as sor_exslikk_net_qty from snitch_db.maplemonk.dp_sales_daily group by 1,2,3 ), j as ( select sp.d as date, sp.l1, sp.category, sp.grp, coalesce(s.shopify_gross_qty,0) as shopify_gross_qty, coalesce(s.shopify_gross_rev,0) as shopify_gross_rev, coalesce(s.shopify_gross_cost,0) as shopify_gross_cost, coalesce(s.shopify_net_qty,0) as shopify_net_qty, coalesce(s.shopify_net_rev,0) as shopify_net_rev, coalesce(s.shopify_net_cost,0) as shopify_net_cost, coalesce(s.mp_gross_qty,0) as mp_gross_qty, coalesce(s.mp_gross_rev,0) as mp_gross_rev, coalesce(s.mp_gross_cost,0) as mp_gross_cost, coalesce(s.mp_net_qty,0) as mp_net_qty, coalesce(s.mp_net_rev,0) as mp_net_rev, coalesce(s.mp_net_cost,0) as mp_net_cost, coalesce(s.offline_gross_qty,0) as offline_gross_qty, coalesce(s.offline_gross_rev,0) as offline_gross_rev, coalesce(s.offline_gross_cost,0) as offline_gross_cost, coalesce(s.offline_net_qty,0) as offline_net_qty, coalesce(s.offline_net_rev,0) as offline_net_rev, coalesce(s.offline_net_cost,0) as offline_net_cost, coalesce(s.sor_gross_qty,0) as sor_gross_qty, coalesce(s.sor_gross_rev,0) as sor_gross_rev, coalesce(s.sor_gross_cost,0) as sor_gross_cost, coalesce(s.sor_net_qty,0) as sor_net_qty, coalesce(s.sor_net_rev,0) as sor_net_rev, coalesce(s.sor_net_cost,0) as sor_net_cost, coalesce(s.sor_exslikk_qty,0) as sor_exslikk_qty, coalesce(s.sor_exslikk_net_qty,0) as sor_exslikk_net_qty from spine sp left join s on s.date = sp.d and s.l1 = sp.l1 and s.category = sp.category ), w as ( select j.*, sum(shopify_gross_qty + mp_gross_qty) over (partition by l1, category order by date rows between 29 preceding and current row) as l30_online, sum(offline_gross_qty) over (partition by l1, category order by date rows between 29 preceding and current row) as l30_offline, sum(sor_exslikk_qty) over (partition by l1, cat